"""Författade lösningar, inte automatiskt gissade rubriker."""
from pathlib import Path
import runpy,json,math,re
H=runpy.run_path(str(Path(__file__).with_name('felrapporter-2026-11-09.py')))
m,st,sol=[H[k] for k in ['m','st','sol']]
b=H['read']('uppgifter2.js');old={q['id']:json.loads(json.dumps(q)) for q in b};d={q['id']:q for q in b}
S={}
S['6.11']=sol([st(r'Skeppet är i rörelse: \(L=L_0\sqrt{1-v^2/c^2}\)','<p>41,2 m är den förkortade längden i ditt system. Vi söker längden i skeppets vilosystem.</p>'),st('Lös ut skeppets egenlängd',m(r'L_0=\frac{41{,}2}{\sqrt{1-0{,}850^2}}\approx78{,}2\ \mathrm m'))],'Skeppets längd i vila är cirka 78,2 m.')
S['6.12']=sol([st(r'Jorden och stjärnan definierar egenlängden: \(L_0=135\) ljusår','<p>I skeppets system rör sig både jorden och stjärnan. Avståndet mellan dem är därför kortare.</p>'),st(r'Längdkontraktion: \(L=L_0\sqrt{1-v^2/c^2}\)',m(r'\begin{aligned}L&=135\sqrt{1-(2{,}90/3{,}00)^2}\\&\approx34{,}6\ \mathrm{ljusår}\end{aligned}')),st('Ljusfartens tabellvärde påverkar svaret här',r'<p>Här har vi använt \(c=3{,}00\cdot10^8\) m/s. Med \(c=2{,}998\cdot10^8\) m/s blir svaret cirka 34,2 ljusår. Skillnaden märks eftersom farten ligger nära ljusfarten.</p>')],'Cirka 34,6 ljusår med c = 3,00·10⁸ m/s; cirka 34,2 ljusår med c = 2,998·10⁸ m/s.')
S['6.13']=sol([st(r'Avståndskvoten: \(L/L_0=\sqrt{1-v^2/c^2}\)',r'<p>49 ljusår är avståndet i jordens och stjärnans gemensamma vilosystem. Ombord ska det vara 35 ljusår.</p>'+m(r'\frac{35}{49}=\sqrt{1-v^2/c^2}')),st('Kvadrera kvoten och lös ut farten',m(r'\frac vc=\sqrt{1-(35/49)^2}\approx0{,}700'))],'Farten behöver vara cirka 0,70c.')
S['6.14']=sol([st(r'Linjalens längdriktning kontraheras: \(L=L_0\sqrt{1-v^2/c^2}\)',r'<p>Här är \(L_0=1{,}00\) m och \(L=0{,}90\) m. De är längder uppmätta samtidigt i respektive system, inte längder avlästa från ett fotografi.</p>'),st('Lös ut farten ur längdkvoten',m(r'\frac vc=\sqrt{1-(0{,}90/1{,}00)^2}\approx0{,}436'))],'Cirka 0,44c.')
S['6.15']=sol([st(r'Ett ljusår är en sträcka: \(s=ct\)',m(r'\begin{aligned}1\ \mathrm{år}&=365{,}25\cdot24\cdot3600\ \mathrm s\\1\ \mathrm{ljusår}&\approx9{,}46\cdot10^{15}\ \mathrm m\end{aligned}')),st('Multiplicera med avståndet 8,6 ljusår',m(r'8{,}6\cdot9{,}46\cdot10^{15}\approx8{,}14\cdot10^{16}\ \mathrm m'))],r'Cirka \(8{,}1\cdot10^{16}\) m.')
S['6.16']=sol([st('Använd jordens avstånd och jordens tid','<p>Från jorden är avståndet 8,6 ljusår. Farten 0,95c motsvarar 0,95 ljusår per år. Ingen Lorentzfaktor behövs för denna fråga.</p>'),st(r'Konstant fart: \(t=L_0/v\)',m(r't=\frac{8{,}6}{0{,}95}\approx9{,}05\ \mathrm{år}'))],'Enligt jorden tar resan cirka 9,1 år.')
S['6.17']=sol([st(r'Jordens restid: \(t=L_0/v\)',m(r't=8{,}6/0{,}95\approx9{,}053\ \mathrm{år}')),st(r'Ombord mäts egentiden: \(\tau=t\sqrt{1-v^2/c^2}\)',r'<p>Samma klocka följer resenären från avfärd till ankomst. Använd jordens oavrundade restid.</p>'+m(r'\tau=\frac{8{,}6}{0{,}95}\sqrt{1-0{,}95^2}\approx2{,}83\ \mathrm{år}'))],'Resenären upplever cirka 2,8 år.')
S['6.18']=sol([st(r'Solens och Sirius vilosystem ger \(L_0=8{,}6\) ljusår','<p>Resenären mäter i stället ett förkortat avstånd mellan de två himlakropparna.</p>'),st(r'Längdkontraktion: \(L=L_0\sqrt{1-v^2/c^2}\)',m(r'\begin{aligned}L&=8{,}6\sqrt{1-0{,}95^2}\\&\approx2{,}685\ \mathrm{ljusår}\end{aligned}'))],'Avståndet ombord är cirka 2,7 ljusår.')
S['6.20']=sol([st(r'Jordfasta punkter ger \(L_0=625\) km','<p>267 km är längden mellan samma punkter, uppmätt samtidigt i skeppets referenssystem.</p>'),st(r'Lös ut farten: \(v/c=\sqrt{1-(L/L_0)^2}\)',m(r'v/c=\sqrt{1-(267/625)^2}\approx0{,}904'))],'Farten är cirka 0,90c.')
S['6.21']=sol([st(r'Tågets egenlängd är \(L_0=101\) m','<p>Markobservatören mäter tågets båda ändar samtidigt i markens system. Tåget rör sig och längdkontraheras.</p>'),st(r'Längdkontraktion: \(L=L_0\sqrt{1-v^2/c^2}\)',m(r'L=101\sqrt{1-0{,}20^2}\approx98{,}96\ \mathrm m')),st('Jämför med tunnelns 100 m',r'<p>98,96 m är mindre än 100 m. I markens system ryms därför tåget helt i tunneln under ett kort ögonblick.</p>')],'Cirka 99,0 m. Ja, tåget ryms i markens referenssystem.')
S['6.22']=sol([st(r'Tunneln är i vila på marken: \(L_0=100\) m','<p>Lokföraren mäter tunnelns båda ändar samtidigt i tågets system. Det är då tunneln som rör sig.</p>'),st(r'Längdkontraktion av tunneln: \(L=L_0\sqrt{1-v^2/c^2}\)',m(r'L=100\sqrt{1-0{,}20^2}\approx97{,}98\ \mathrm m'))],'Tunneln är cirka 98 m lång i tågets system.')
S['6.27']=sol([st(r'Tidsdilatation ger \(\tau/t=\sqrt{1-v^2/c^2}\)','<p>12,0 år är jordens tid. De 9,2 åren ombord mäts av klockan som följer med hela resan.</p>'),st('Bestäm farten ur tidskvoten',m(r'v/c=\sqrt{1-(9{,}2/12{,}0)^2}\approx0{,}642')),st(r'Planetavståndet i jordens system: \(L_0=vt\)',m(r'\begin{aligned}L_0&=12{,}0\sqrt{1-(9{,}2/12{,}0)^2}\\&\approx7{,}70\ \mathrm{ljusår}\end{aligned}'))],'Planeten ligger cirka 7,7 ljusår bort i jordens system.')
S['6.28']=sol([st(r'Bestäm farten från \(L/L_0=\sqrt{1-v^2/c^2}\)',r'<p>Jordens avstånd är 4,3 ljusår, medan resenären mäter 2,5 ljusår.</p>'+m(r'v/c=\sqrt{1-(2{,}5/4{,}3)^2}\approx0{,}814')),st(r'Jordens restid: \(t=L_0/v\)',m(r't=\frac{4{,}3}{\sqrt{1-(2{,}5/4{,}3)^2}}\approx5{,}28\ \mathrm{år}'))],'Cirka 5,3 år enligt jorden.')
S['6.29']=sol([st('Bara sidan längs rörelsen förkortas','<p>De två sidorna vinkelrätt mot rörelsen är fortfarande 1,0 km i jordens system.</p>'),st(r'Sidan längs rörelsen: \(L=L_0\sqrt{1-v^2/c^2}\)',m(r'L=1{,}0\sqrt{1-0{,}94^2}\approx0{,}341\ \mathrm{km}')),st(r'Volym: \(V=L\cdot b\cdot h\)',m(r'\begin{aligned}V&\approx0{,}341\cdot1{,}0\cdot1{,}0\\&=0{,}341\ \mathrm{km^3}\end{aligned}'))],'Volymen mätt från jorden är cirka 0,34 km³.')
S['6.62']=sol([st('100 m är skeppets längd i vila','<p>Jorden mäter längden hos ett skepp som passerar med 0,6c.</p>'),st(r'Längdkontraktion: \(L=L_0\sqrt{1-v^2/c^2}\)',m(r'\begin{aligned}L&=100\sqrt{1-0{,}6^2}\\&=100\cdot0{,}8=80\ \mathrm m\end{aligned}'))],'Från jorden mäts längden till 80 m.')
S['6.63']=sol([st(r'Egenlängden är \(L_0=50\) m','<p>Det är skeppet som rör sig relativt observatören på jorden, så dess längd blir mindre än 50 m.</p>'),st(r'Längdkontraktion: \(L=L_0\sqrt{1-v^2/c^2}\)',m(r'L=50\sqrt{1-0{,}9^2}\approx21{,}8\ \mathrm m'))],'Cirka 22 m från jorden.')
S['6.64']=sol([st(r'80 % av egenlängden betyder \(L/L_0=0{,}80\)',m(r'0{,}80=\sqrt{1-v^2/c^2}')),st('Kvadrera och lös ut farten',m(r'\begin{aligned}(v/c)^2&=1-0{,}80^2=0{,}36\\v/c&=0{,}60\end{aligned}'))],'Farten är 0,60c.')
S['6.330']=sol([st(r'Skeppets egenlängd är \(L_0=100\) m','<p>Figuren jämför samma skepp i vila och mätt från jorden när det rör sig.</p>'),st(r'Längdkontraktion: \(L=L_0\sqrt{1-v^2/c^2}\)',m(r'\begin{aligned}L&=100\sqrt{1-0{,}60^2}\\&=100\cdot0{,}80=80\ \mathrm m\end{aligned}'))],'Skeppet är 80 m långt mätt från jorden.')
S['6.331']=sol([st(r'Stavens egenlängd är \(L_0=2{,}0\) m','<p>Längdriktningen är parallell med rörelsen, så längdkontraktionen gäller hela stavens längd.</p>'),st(r'Längdkontraktion: \(L=L_0\sqrt{1-v^2/c^2}\)',m(r'\begin{aligned}L&=2{,}0\sqrt{1-0{,}80^2}\\&=2{,}0\cdot0{,}60=1{,}2\ \mathrm m\end{aligned}'))],'Laboratoriet mäter 1,2 m.')
S['6.332']=sol([st(r'Jorden och stjärnan ger \(L_0=4{,}2\) ljusår','<p>De är i vila relativt varandra. Resenärerna ser dem båda röra sig och mäter ett kortare avstånd.</p>'),st(r'Längdkontraktion: \(L=L_0\sqrt{1-v^2/c^2}\)',m(r'\begin{aligned}L&=4{,}2\sqrt{1-0{,}90^2}\\&\approx1{,}83\ \mathrm{ljusår}\end{aligned}'))],'Resenärerna mäter cirka 1,8 ljusår.')
S['6.333']=sol([st('Längdkontraktion gäller längs rörelsen','<p>Skeppet rör sig åt höger. Måttet från vänster till höger blir kortare. Höjd och bredd vinkelrätt mot rörelsen förändras inte.</p>')],'Bara måttet i rörelseriktningen blir kortare.')
S['6.334']=sol([st('Egenlängden mäts i föremålets vilosystem','<p>Astronauten är i vila relativt skeppet och mäter därför egenlängden. Stationsteknikern mäter ett skepp i rörelse och får en kortare längd.</p>')],'Astronauten mäter skeppets egenlängd.')
S['6.335']=sol([st(r'Gammavärdet är redan givet: \(\gamma=2{,}5\)','<p>50 m är sondens egenlängd. Vi behöver inte först räkna ut farten.</p>'),st(r'Längdkontraktion: \(L=L_0/\gamma\)',m(r'L=50/2{,}5=20\ \mathrm m'))],'Sonden är 20 m lång mätt från planeten.')
S['6.336']=sol([st(r'Atmosfären är i vila på jorden: \(L_0=15\) km','<p>I myonens system rör sig marken mot myonen. Sträckan genom atmosfären är längdkontraherad.</p>'),st(r'Längdkontraktion: \(L=L_0\sqrt{1-v^2/c^2}\)',m(r'L=15\sqrt{1-0{,}995^2}\approx1{,}498\ \mathrm{km}'))],'Sträckan i myonens vilosystem är cirka 1,5 km.')
S['6.337']=sol([st(r'Tunnelns egenlängd är \(L_0=300\) m','<p>Från tåget är det tunneln som rör sig. Tågets egen längd behövs inte.</p>'),st(r'Längdkontraktion: \(L=L_0\sqrt{1-v^2/c^2}\)',m(r'L=300\sqrt{1-0{,}50^2}\approx259{,}8\ \mathrm m'))],'Tunneln mäts till cirka 260 m från tåget.')
S['6.338']=sol([st(r'Längdernas kvot: \(L/L_0=\sqrt{1-v^2/c^2}\)',m(r'L/L_0=\sqrt{1-0{,}60^2}=0{,}80')),st('Omvandla andelen till procent',m(r'0{,}80\cdot100\ \%=80\ \%'))],'Längden är 80 % av egenlängden.')
S['6.339']=sol([st('Måttbandet följer med skeppet','<p>Astronauten och måttbandet är i vila relativt skeppet. Hen mäter därför skeppets egenlängd, inte den kortare längd som en observatör på jorden får.</p>')],'Astronauten mäter skeppets vanliga egenlängd.')
for id,s in S.items():d[id]['s']=s;d[id]['miniräknare']=True;d[id]['geogebra']=False
# Felaktigt maskinfacit gav även 101 m rätt: den exakta längden är under 99 m.
d['6.21']['t']=re.sub(r'(?:Ange tågets längd med en decimal\. )*Får det plats','Ange tågets längd med en decimal. Får det plats',d['6.21']['t'])
d['6.22']['t']=d['6.22']['t'].replace('Lokföraren tittar framåt genom tunneln.', 'Lokföraren mäter avståndet mellan tunnelns ändar samtidigt i tågets referenssystem.')
d['6.21']['rättSvar']=101*math.sqrt(1-.2**2);d['6.21']['tolerans']=.05
